def find_repeated_substrings_of_length(s, k):
    if k == 0 or k < 0 or k > len(s):
        return []
    seen = {}
    result = []
    for i in range(len(s) - k + 1):
        substring = s[i:i+k]
        if substring in seen:
            # Only add the first occurrence to avoid duplicates in the result
            if seen[substring] == 0:
                result.append(substring)
                seen[substring] = 1  # Mark as already added
        else:
            seen[substring] = 0  # Mark as not yet added
    return result
```

